A(1,'مهار و کشتن: استاتیک در برابر سیدال',[3],
 'پسوند «استاتیک» به مهار رشد و «سیدال» به کشتن اشاره دارد. نام گروه هدف، مانند باکتری یا قارچ، نشان می‌دهد این اثر دربارهٔ چه میکروارگانیسمی بیان شده است.',
 [['زیست‌کش (Biocide)', 'عنوان کلیِ موادی که میکروارگانیسم‌ها را از بین می‌برند یا غیرفعال می‌کنند.'], ['استاتیک (Static)', 'رشد یا تکثیر را مهار می‌کند؛ مهار رشد الزاماً به معنی مرگ میکروب نیست.'], ['سیدال (Cidal)', 'اثر کشنده دارد؛ برای مثال باکتری‌سیدال یعنی کشندهٔ باکتری.'], ['نام گروه هدف', 'در باکتریواستاتیک و قارچ‌کش، بخش اول اصطلاح گروه میکروبی هدف را مشخص می‌کند.']],
 'اول «روی چه چیزی؟»، بعد «با چه نوع اثری؟».',
 [('استاتیک و سیدال چه تفاوت مفهومی دارند؟','استاتیک به مهار و سیدال به اثر کشنده اشاره دارد؛ این دو واژه را نباید هم‌معنا دانست.',['مهار','کشتن']),
  ('پیشوند و پسوند یک اصطلاح ضدمیکروبی چه اطلاعاتی می‌دهند؟','پیشوند گروه هدف و پسوند نوع اثر را مشخص می‌کند.',['گروه هدف','نوع اثر'])])

A(1,'استریلیزاسیون، ضدعفونی و آنتی‌سپتیک',[3,4],
 'استریل‌سازی همهٔ اشکال میکروبی را هدف می‌گیرد؛ ضدعفونی چنین دامنه‌ای ندارد. آنتی‌سپسیس به کاربرد مواد ضدمیکروبی روی بافت زنده، مانند پوست، گفته می‌شود.',
 [['استریل‌سازی (Sterilization)', 'حذف یا نابودی همهٔ اشکال حیات میکروبی، از جمله اسپورهای باکتریایی.'], ['ضدعفونی (Disinfection)', 'حذف بسیاری از عوامل بیماری‌زا روی اجسام بی‌جان؛ لزوماً همهٔ اسپورها را از بین نمی‌برد.'], ['آنتی‌سپسیس (Antisepsis)', 'استفاده از مادهٔ ضدمیکروبیِ مناسب روی بافت زنده، مانند پوست. خود ماده را آنتی‌سپتیک می‌نامند.'], ['نگهداری فرآورده (Preservation)', 'جلوگیری از رشد یا فساد میکروبی در مواد غذایی، دارویی و آرایشی.']],
 '«همهٔ اشکال»، «کاهش عوامل»، «بافت زنده»، «حفظ فرآورده».',
 [('چرا ضدعفونی را با استریلیزاسیون برابر نمی‌گیریم؟','در تعریف جزوه، استریلیزاسیون همهٔ اشکال میکروبی را شامل می‌شود؛ ضدعفونی چنین معنای مطلقی ندارد.',['دامنهٔ حذف','اسپور']),
  ('آنتی‌سپتیک و نگهداری را با زمینهٔ کاربردشان مقایسه کن.','اولی در ارتباط با بافت زنده و دومی در ارتباط با جلوگیری از رشد میکروبی در فرآورده‌ها مطرح می‌شود.',['بافت زنده','فرآورده'])])

A(1,'نقشهٔ روش‌های کنترل: سه دستهٔ کلی',[2,5,8,9,10,11],
 'کنترل میکروبی می‌تواند با عوامل فیزیکی، جداسازی مکانیکی یا مواد شیمیایی انجام شود. دانستن نوع روش کافی نیست؛ باید بدانیم میکروب کشته می‌شود، جدا می‌شود یا فقط رشدش مهار می‌شود.',
 [['روش‌های فیزیکی', 'عواملی مانند گرما و پرتوها با اثر بر اجزای سلول، میکروب را غیرفعال می‌کنند. نتیجه به نوع روش و شرایط آن بستگی دارد.'], ['جداسازی مکانیکی', 'میکروب از ماده یا محیط جدا می‌شود؛ برای مثال فیلتراسیون الزاماً میکروب را نمی‌کشد.'], ['مواد شیمیایی', 'مواد ضدمیکروبی می‌توانند به غشا، پروتئین‌ها یا دیگر اجزای میکروب آسیب بزنند.'], ['نوع روش و نتیجهٔ آن', '«فیزیکی» نوع روش را می‌گوید؛ «استریل‌سازی» نتیجهٔ موردنظر را. این دو نام، پاسخ دو پرسش متفاوت‌اند.']],
 'نوع روش یک محور است؛ هدف کنترل، محور دیگر.',
 [('سه دستهٔ اصلی این بخش از جزوه کدام‌اند؟','فیزیکی، مکانیکی و شیمیایی.',['سه دسته']),
  ('چرا نام یک دسته، به‌تنهایی نتیجهٔ نهایی را مشخص نمی‌کند؟','دسته‌بندی به نوع روش اشاره دارد، در حالی که اصطلاح‌هایی مانند ضدعفونی و استریلیزاسیون به هدف و دامنهٔ حذف اشاره می‌کنند.',['نوع روش','دامنهٔ حذف'])])

A(2,'نایسریا: نام جنس و مقایسهٔ دو گونه',[12,21],
 'گنوکوک و مننگوکوک هر دو دیپلوکوک گرم منفی از جنس نایسریا هستند. وجود کپسول در مننگوکوک، تفاوت ساختاری مهمی در مقایسهٔ این دو است.',
 [['جنس نایسریا (Neisseria)', 'جنس مشترک دو گونهٔ گنوروئا و مننژیتیدیس.'], ['گنوکوک', 'نام رایج نایسریا گنوروئا؛ در این جزوه بیشتر در ارتباط با عفونت‌های مخاطی مطرح است.'], ['مننگوکوک', 'نام رایج نایسریا مننژیتیدیس؛ کپسول در بیماری تهاجمی آن اهمیت دارد.'], ['ویژگی مشترک', 'هر دو به‌صورت دیپلوکوک گرم منفی دیده می‌شوند. دیپلوکوک یعنی دو سلول کروی کنار هم.'], ['تفاوت ساختاری', 'مننگوکوک کپسول پلی‌ساکاریدی دارد؛ گنوکوک چنین کپسول متعارفی ندارد.']],
 'یک جنس، دو نام گونه؛ شباهت کلی، تفاوت مشخص.',
 [('نام رایج دو گونهٔ اصلی این بخش چیست؟','گنوکوک برای نایسریا گنوروئا و مننگوکوک برای نایسریا مننژیتیدیس.',['دو نام','تطبیق درست']),
  ('کدام ویژگی ساختاری در مقایسهٔ جزوه برجسته است؟','کپسول در مننگوکوک؛ جزوه این ویژگی را از محورهای تفاوت دو گونه قرار می‌دهد.',['کپسول','مننگوکوک'])])

A(2,'گنوکوک: استقرار، التهاب و عارضه',[17,18],
 'گنوکوک پس از اتصال به مخاط می‌تواند التهاب و عفونت موضعی ایجاد کند. در بعضی موارد، گسترش فراتر از محل اولیه به عوارضی مانند درگیری مفصل می‌انجامد.',
 [['استقرار روی مخاط', 'اتصال و باقی‌ماندن باکتری در محل؛ حضور باکتری و بروز علامت لزوماً هم‌زمان نیستند.'], ['التهاب', 'پاسخ میزبان به حضور و فعالیت عامل؛ بخشی از علائم و آسیب از این پاسخ ناشی می‌شود.'], ['عفونت موضعی', 'درگیری در محل اولیه، مانند مخاط تناسلی.'], ['عفونت منتشر', 'گسترش عامل فراتر از محل نخستین؛ درگیری مفصل یکی از مثال‌های جزوه است.'], ['عفونت چشم نوزاد', 'درگیری چشمی مرتبط با مواجهه هنگام تولد، از تظاهرهای مطرح در جزوه.']],
 'حضور عامل، واکنش میزبان و پیامد را جدا تعریف کن.',
 [('کلونیزاسیون و التهاب چه تفاوتی دارند؟','کلونیزاسیون به استقرار میکروارگانیسم و التهاب به واکنش میزبان اشاره دارد.',['استقرار','واکنش میزبان']),
  ('تفاوت مفهومی عفونت موضعی و منتشر چیست؟','موضعی به محل محدود مربوط است؛ منتشر با گسترش فراتر از محل اولیه توصیف می‌شود.',['محدود','گسترش'])])

A(3,'بروسلوز: ارتباط انسان و حیوان و علائم عمومی',[25,26,29],
 'بروسلا نام باکتری و بروسلوز یا تب مالت نام بیماری است. تب، تعریق، خستگی و درد از تظاهرهای عمومی این بیماری مشترک انسان و حیوان‌اند.',
 [['بروسلا', 'نام جنس باکتری؛ آن را با نام بیماری اشتباه نکن.'], ['بروسلوز یا تب مالت', 'بیماری مشترک انسان و حیوان که با گونه‌های بروسلا ایجاد می‌شود.'], ['تب مواج', 'اصطلاحی برای بالا و پایین رفتن تب در طول سیر بیماری.'], ['علائم عمومی', 'تب، تعریق، خستگی و درد؛ این علائم به‌تنهایی اختصاصی بروسلوز نیستند.'], ['حاد و مزمن', 'توصیف سیر زمانی بیماری‌اند، نه نام دو عامل متفاوت.']],
 'بروسلا = نام عامل؛ بروسلوز = نام بیماری؛ حاد و مزمن = توصیف سیر.',
 [('نام عامل، نام بیماری و توصیف سیر را از هم جدا کن.','بروسلا نام عامل، بروسلوز نام بیماری، و حاد یا مزمن توصیف سیر است.',['عامل','بیماری','سیر']),
  ('در مرور عمومی این بخش، چه علائمی مطرح شده‌اند؟','تب، تعریق، خستگی و درد؛ این‌ها نکات مرور جزوه‌اند.',['تب','تعریق','خستگی','درد'])])

A(3,'تولارمی: نام‌ها و الگوهای تظاهر',[25,32],
 'نام شکل‌های بالینی تولارمی، محل درگیری را توصیف می‌کند: زخم و غدد لنفاوی، چشم و غدد لنفاوی، یا غدد لنفاوی بدون زخم آشکار.',
 [['عامل', 'فرانسیسلا تولارنسیس؛ نام بیماری، تولارمی است.'], ['اولسروگلاندولار', 'زخم موضعی همراه با بزرگ‌شدن غدد لنفاوی مرتبط با آن ناحیه.'], ['اکولوگلاندولار', 'درگیری چشم همراه با غدد لنفاوی ناحیه‌ای.'], ['گلاندولار', 'درگیری غدد لنفاوی بدون زخم آشکار.'], ['ارزش ظاهر ضایعه', 'ظاهر زخم سرنخ است؛ برای تشخیص، شرح‌حال و شواهد دیگر هم لازم‌اند.']],
 'اولسرو: زخم؛ اکولو: چشم؛ گلاندولار: غدد.',
 [('سه فرم نام‌برده‌شده را در حد واژه‌شناسی مقایسه کن.','اولسروگلاندولار با زخم و غدد، اکولوگلاندولار با چشم و غدد، و گلاندولار با غدد بدون زخم در متن توضیح داده شده است.',['زخم','چشم','غدد']),
  ('چرا نباید از ظاهر یک زخم نتیجهٔ قطعی گرفت؟','خود جزوه تصریح می‌کند که ظاهر زخم به‌تنهایی برای تشخیص قطعی کافی نیست.',['محدودیت ظاهر'])])

A(4,'سه نقشه برای جمع‌بندی فایل',[2,12,25],
 'برای مرور این جزوه، ابتدا اصطلاح‌های کنترل میکروبی، سپس تفاوت دو نایسریا و در پایان نام عامل و تظاهرهای بروسلوز و تولارمی را مرور کن.',
 [['کنترل میکروبی', 'نام اصطلاح، نوع اثر و دامنهٔ حذف را در یک جدول بنویس.'], ['دو نایسریا', 'جنس و شکل مشترک را کنار تفاوت کپسول قرار بده.'], ['بیماری‌های مشترک انسان و حیوان', 'برای هر مورد، نام عامل، نام بیماری و تظاهرهای شاخص را بنویس.'], ['مرور از حافظه', 'جدول‌ها را بپوشان و برای هر ردیف یک توضیح کامل بگو؛ سپس نکات جاافتاده را پیدا کن.']],
 'تعریف‌ها، مقایسهٔ گونه‌ها، نام‌ها و تظاهرها.',
 [('چرا بهتر است سه نقشهٔ جدا بسازیم؟','چون تعریف روش کنترل، مقایسهٔ گونه‌ها و توصیف بالینی سه سطح متفاوت از اطلاعات‌اند.',['سه سطح متفاوت']),
  ('برای مرور این فایل چه خروجی کوتاهی می‌سازی؟','یک جدول تعریف‌ها، یک جدول مقایسهٔ دو نایسریا و یک جدول نام عامل، بیماری و تظاهرهای عمومی.',['سه جدول'])])

